244	func TestConcurrentBatchesNoDuplicateCursors(t *testing.T) {
245		s, _ := Open("")
246		defer func() { _ = s.Close() }()
247	
248		const goroutines = 16
249		const perBatch = 25
250	
251		var wg sync.WaitGroup
252		errCh := make(chan error, goroutines)
253		var mu sync.Mutex
254		all := make([]Result, 0, goroutines*perBatch)
255	
256		for g := 0; g < goroutines; g++ {
257			wg.Add(1)
258			go func(g int) {
259				defer wg.Done()
260				batch := make([]Change, perBatch)
261				for i := range batch {
262					id := fmt.Sprintf("g%d-i%d", g, i)
263					batch[i] = Change{ID: id, DeviceID: "dev", Payload: json.RawMessage(fmt.Sprintf(`{"g":%d,"i":%d}`, g, i))}
264				}
265				results, err := s.PostChanges("doc", batch)
266				if err != nil {
267					errCh <- err
268					return
269				}
270				mu.Lock()
271				all = append(all, results...)
272				mu.Unlock()
273			}(g)
274		}
275		wg.Wait()
276		close(errCh)
277		for err := range errCh {
278			t.Fatal(err)
279		}
280	
281		if len(all) != goroutines*perBatch {
282			t.Fatalf("lost records: got %d results", len(all))
283		}
284	
285		seen := make(map[int64]string, len(all))
286		for _, r := range all {
287			if prev, ok := seen[r.Cursor]; ok {
288				t.Fatalf("cursor %d assigned to both %s and %s", r.Cursor, prev, r.ID)
289			}
290			seen[r.Cursor] = r.ID
291		}
292	
293		cursors := make([]int, 0, len(seen))
294		for c := range seen {
295			cursors = append(cursors, int(c))
296		}
297		sort.Ints(cursors)
298		for i, c := range cursors {
299			if c != i+1 {
300				t.Fatalf("cursors not contiguous: position %d has cursor %d", i, c)
301			}
302		}
303	
304		rows, _, err := s.ListChanges("doc", 0, 1000)
305		if err != nil {
306			t.Fatal(err)
307		}
308		if len(rows) != goroutines*perBatch {
309			t.Fatalf("stored rows = %d, want %d", len(rows), goroutines*perBatch)
310		}
311	}
