466		w, body := mergeBody(t, h, "doc", map[string]any{
467			"deviceId": "dev", "baseCursor": 0,
468			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 1}},
469		})
470		if w.Code != 200 {
471			t.Fatal(w.Body.String())
472		}
473		if body["outcome"] != "applied" || body["cursor"].(float64) != 1 {
474			t.Fatalf("applied = %v", body)
475		}
476	
477		// baseCursor ahead -> 400.
478		w, _ = mergeBody(t, h, "doc", map[string]any{
479			"deviceId": "dev", "baseCursor": 9,
480			"change": map[string]any{"id": "cX", "payload": map[string]any{"z": 1}},
481		})
482		if w.Code != http.StatusBadRequest {
483			t.Fatalf("ahead base = %d", w.Code)
484		}
485	
486		// Same id repost -> idempotent with embedded result.
487		w, body = mergeBody(t, h, "doc", map[string]any{
488			"deviceId": "dev", "baseCursor": 1,
489			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 1}},
490		})
491		if w.Code != 200 || body["outcome"] != "idempotent" || body["cursor"].(float64) != 1 {
492			t.Fatalf("idempotent = %d %v", w.Code, body)
493		}
494		res := body["result"].(map[string]any)
495		if res["id"] != "c1" || res["created"] != false || res["cursor"].(float64) != 1 {
496			t.Fatalf("embedded result = %v", res)
497		}
498	
499		// Same id, different payload -> 409.
500		w, _ = mergeBody(t, h, "doc", map[string]any{
501			"deviceId": "dev", "baseCursor": 1,
502			"change": map[string]any{"id": "c1", "payload": map[string]any{"a": 2}},
503		})
504		if w.Code != http.StatusConflict {
505			t.Fatalf("conflict = %d body=%s", w.Code, w.Body.String())
506		}
507	
508		// Seed a second object {"b":2} at cursor 2.
509		w, _ = postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
510			"deviceId": "dev",
511			"changes":  []any{map[string]any{"id": "c2", "payload": map[string]any{"b": 2}}},
512		})
513		if w.Code != 200 {
514			t.Fatal(w.Body.String())
515		}
516	
517		// Stale client at baseCursor 1 posts {"c":3}: disjoint from later {"b":2} -> merged cursor 3.
518		w, body = mergeBody(t, h, "doc", map[string]any{
519			"deviceId": "dev", "baseCursor": 1,
520			"change": map[string]any{"id": "c3", "payload": map[string]any{"c": 3}},
521		})
522		if w.Code != 200 || body["outcome"] != "merged" || body["cursor"].(float64) != 3 {
523			t.Fatalf("merged = %d %v body=%s", w.Code, body, w.Body.String())
524		}
525	
526		// Stale client posts a payload colliding with later key "b" -> 409 zero write.
527		before, _, _ := s.ListChanges("doc", 0, 100)
528		w, _ = mergeBody(t, h, "doc", map[string]any{
529			"deviceId": "dev", "baseCursor": 0,
530			"change": map[string]any{"id": "c4", "payload": map[string]any{"b": 99}},
531		})
532		if w.Code != http.StatusConflict {
533			t.Fatalf("clash = %d body=%s", w.Code, w.Body.String())
534		}
535		after, _, _ := s.ListChanges("doc", 0, 100)
536		if len(after) != len(before) {
537			t.Fatalf("conflict changed row count: before=%d after=%d", len(before), len(after))
538		}
539	}
540	
541	func TestMergeHTTPZeroWriteOnBadBase(t *testing.T) {
542		h, s := newTestHandler(t)
543		// Seed one change.
544		w, _ := postJSON(t, h, "/v1/documents/doc/changes", map[string]any{
545			"deviceId": "dev",
546			"changes":  []any{map[string]any{"id": "seed", "payload": map[string]any{"k": 1}}},
547		})
548		if w.Code != 200 {
549			t.Fatal(w.Body.String())
550		}
551		// A rejected merge (baseCursor ahead) must not write.
552		w, _ = mergeBody(t, h, "doc", map[string]any{
553			"deviceId": "dev", "baseCursor": 5,
