func seedDoc(t *testing.T, s *Store, doc string, n int) {
	t.Helper()
	batch := make([]Change, n)
	for i := range batch {
		batch[i] = Change{
			ID:       fmt.Sprintf("c%d", i+1),
			DeviceID: "dev",
			Payload:  json.RawMessage(fmt.Sprintf(`{"n":%d}`, i+1)),
		}
