108			t.Fatal(err)
109		}
110	
111		cases := []struct {
112			name        string
113			contentType string
114			body        string
115			wantStatus  int
116		}{
117			{"wrong content type", "text/plain", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
118			{"missing content type", "", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
119			{"content type with json suffix", "application/vnd.api+json", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
120			{"malformed json", "application/json", `{"deviceId":"d","changes":[`, http.StatusBadRequest},
121			{"trailing content", "application/json", `{"deviceId":"d","changes":[{"id":"a","payload":1}]}garbage`, http.StatusBadRequest},
122			{"empty deviceId", "application/json", `{"deviceId":"","changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
123			{"missing deviceId", "application/json", `{"changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
124			{"numeric deviceId", "application/json", `{"deviceId":7,"changes":[{"id":"a","payload":1}]}`, http.StatusBadRequest},
125			{"empty changes", "application/json", `{"deviceId":"d","changes":[]}`, http.StatusBadRequest},
126			{"missing changes", "application/json", `{"deviceId":"d"}`, http.StatusBadRequest},
127			{"empty id", "application/json", `{"deviceId":"d","changes":[{"id":"","payload":1}]}`, http.StatusBadRequest},
128			{"numeric id", "application/json", `{"deviceId":"d","changes":[{"id":123,"payload":1}]}`, http.StatusBadRequest},
129			{"missing payload", "application/json", `{"deviceId":"d","changes":[{"id":"a"}]}`, http.StatusBadRequest},
130			{"duplicate ids in batch", "application/json", `{"deviceId":"d","changes":[{"id":"a","payload":1},{"id":"a","payload":2}]}`, http.StatusBadRequest},
131			{"conflicting existing", "application/json", `{"deviceId":"d","changes":[{"id":"existing","payload":2}]}`, http.StatusConflict},
132			{"conflict device mismatch", "application/json", `{"deviceId":"other","changes":[{"id":"existing","payload":{"v":1}}]}`, http.StatusConflict},
133		}
134	
135		for _, tc := range cases {
136			t.Run(tc.name, func(t *testing.T) {
137				r := httptest.NewRequest(http.MethodPost, url, strings.NewReader(tc.body))
138				if tc.contentType != "" {
139					r.Header.Set("Content-Type", tc.contentType)
140				}
141				w := httptest.NewRecorder()
142				h.ServeHTTP(w, r)
143	
144				if w.Code != tc.wantStatus {
145					t.Fatalf("status = %d, want %d, body = %s", w.Code, tc.wantStatus, w.Body.String())
146				}
147				if ct := w.Header().Get("Content-Type"); ct != "application/json" {
148					t.Fatalf("error content type = %q", ct)
149				}
150				var errBody map[string]string
151				if err := json.Unmarshal(w.Body.Bytes(), &errBody); err != nil || errBody["error"] == "" {
152					t.Fatalf("error body = %s", w.Body.String())
153				}
154			})
155		}
156	}
